    factsAdvanced: {
      de: ["Gegründet am 8. August 1854 als Ersatz für das zerstörte San Salvador.", "Diente von 1854 bis 1859 als provisorische Hauptstadt des Landes.", "Liegt auf einer durchschnittlichen Höhe von etwa 920 Metern über dem Meer.", "Der Palacio Municipal wurde im Jahr 1911 im eklektischen Stil erbaut.", "Das Stadtgebiet umfasst eine Fläche von rund 112 Quadratkilometern.", "Beheimatet das Tecleño-Museum, das die lokale Geschichte dokumentiert."],
      hu: ["1854. augusztus 8-án alapították a romba dőlt San Salvador pótlására.", "1854 és 1859 között az ország ideiglenes fővárosaként szolgált.", "Átlagosan 920 méteres tengerszint feletti magasságban helyezkedik el.", "A Városháza (Palacio Municipal) 1911-ben épült eklektikus stílusban.", "A város területe körülbelül 112 négyzetkilométert tesz ki.", "Itt található a Tecleño Múzeum, amely a helyi történelmet mutatja be."],
      ro: ["Fondat pe 8 august 1854 pentru a înlocui orașul San Salvador distrus.", "A servit drept capitală provizorie a țării între 1854 și 1859.", "Situat la o altitudine medie de aproximativ 920 de metri deasupra mării.", "Palacio Municipal a fost construit în anul 1911 în stil eclectic.", "Teritoriul orașului acoperă o suprafață de circa 112 kilometri pătrați.", "Găzduiește Muzeul Tecleño, care documentează istoria locală."],
      en: ["Founded on August 8, 1854, to replace the destroyed San Salvador.", "Served as the provisional national capital from 1854 to 1859.", "Located at an average altitude of approximately 920 meters above sea level.", "The Palacio Municipal was constructed in 1911 in an eclectic style.", "The city area covers approximately 112 square kilometers.", "Home to the Tecleño Museum, which documents local history."],
      es: ["La ciudad fue fundada para trasladar allí la capital tras un fuerte terremoto.", "Aquí se encuentra el Palacio de la Cultura.", "Santa Tecla es considerada una de las ciudades más modernas y seguras del país."],
      pt: ["A cidade foi fundada para transferir a capital para lá após um forte sismo.", "Aqui encontra-se o Palácio da Cultura (Palacio de la Cultura).", "Santa Tecla é considerada uma das cidades mais modernas e seguras do país."],
      fr: ["La ville a été fondée pour y transférer la capitale après un grave tremblement de terre.", "On y trouve le Palais de la Culture (Palacio de la Cultura).", "Santa Tecla est considérée comme l'une des villes les plus modernes et les plus sûres du pays."],
    },
